'use client'

import * as React from 'react'
import { useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { Button, type ButtonProps } from '@/components/ui/button'

export type ActionButtonState = 'idle' | 'pending' | 'success' | 'error'

export interface ActionButtonProps extends Omit<
  ButtonProps,
  'loading' | 'loadingLabel' | 'loadingIndicator' | 'onClick'
> {
  /** Controlled state; when set, the result of `onAction` is ignored. */
  state?: ActionButtonState
  /** Default state for uncontrolled mode. */
  defaultState?: ActionButtonState
  /** Async action whose promise lifecycle drives the state. Receives an AbortSignal. */
  onAction?: (signal: AbortSignal) => Promise<void>
  /** Fired whenever internal state changes (uncontrolled mode). */
  onStateChange?: (state: ActionButtonState) => void
  /** Minimum ms to show the pending state, to prevent flicker. Defaults to 0. */
  minPendingMs?: number
  /** Ms before success/error resets to idle. Defaults to 2000; 0 disables. */
  resetDelayMs?: number
  /** Label content shown in idle state. */
  idleLabel?: React.ReactNode
  /** Label content shown in pending state. */
  pendingLabel?: React.ReactNode
  /** Label content shown in success state. */
  successLabel?: React.ReactNode
  /** Label content shown in error state. */
  errorLabel?: React.ReactNode
  /** Icon shown in idle state. */
  idleIcon?: React.ReactNode
  /** Icon shown in pending state. Defaults to a spinner. */
  pendingIcon?: React.ReactNode
  /** Icon shown in success state. Defaults to a checkmark. */
  successIcon?: React.ReactNode
  /** Icon shown in error state. Defaults to an × glyph. */
  errorIcon?: React.ReactNode
  /** Custom render per state. Overrides the individual label/icon props. */
  renderState?: (state: ActionButtonState) => React.ReactNode
  /** Accessible live-region announcement per state. */
  announcements?: Partial<Record<ActionButtonState, string>>
  /** onClick passthrough, fires only in idle state. Does not track async. */
  onClick?: React.MouseEventHandler<HTMLButtonElement>
}

function DefaultSpinnerIcon() {
  return (
    <svg
      className="size-4 animate-spin motion-reduce:animate-none"
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
    >
      <circle
        cx="12"
        cy="12"
        r="10"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        className="opacity-25"
      />
      <path
        d="M12 2a10 10 0 0 1 10 10"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        className="opacity-75"
      />
    </svg>
  )
}

function DefaultCheckIcon() {
  return (
    <svg className="size-4" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path
        d="M5 13l4 4L19 7"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

function DefaultErrorIcon() {
  return (
    <svg className="size-4" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path
        d="M6 6l12 12M6 18L18 6"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
      />
    </svg>
  )
}

function StateLayer({
  active,
  children,
  reducedMotion,
  animateEnabled,
}: {
  active: boolean
  children: React.ReactNode
  reducedMotion: boolean
  animateEnabled: boolean
}) {
  return (
    <span
      aria-hidden={!active}
      className={cn(
        'absolute inset-0 flex items-center justify-center gap-2',
        reducedMotion || !animateEnabled
          ? active
            ? 'opacity-100'
            : 'opacity-0'
          : [
              'transition-[opacity,scale,filter] duration-(--motion-dur-base) ease-(--motion-ease-in-out)',
              active
                ? 'scale-100 opacity-100 blur-none'
                : 'pointer-events-none scale-95 opacity-0 blur-[1px]',
            ],
        !animateEnabled && !active && 'pointer-events-none',
        'motion-reduce:transition-none motion-reduce:transform-none motion-reduce:filter-none',
      )}
    >
      {children}
    </span>
  )
}

function useControlledActionState(
  controlledState: ActionButtonState | undefined,
  defaultState: ActionButtonState | undefined,
  onStateChange: ((s: ActionButtonState) => void) | undefined,
): [ActionButtonState, (s: ActionButtonState) => void] {
  const [internalState, setInternalState] = React.useState<ActionButtonState>(
    defaultState ?? 'idle',
  )

  const isControlled = controlledState !== undefined
  const currentState = isControlled ? controlledState : internalState

  const setState = React.useCallback(
    (next: ActionButtonState) => {
      if (!isControlled) {
        setInternalState(next)
      }
      onStateChange?.(next)
    },
    [isControlled, onStateChange],
  )

  return [currentState, setState]
}

export const ActionButton = React.forwardRef<HTMLButtonElement, ActionButtonProps>(
  (
    {
      state: controlledState,
      defaultState,
      onAction,
      onStateChange,
      minPendingMs = 0,
      resetDelayMs = 2000,
      idleLabel,
      pendingLabel,
      successLabel,
      errorLabel,
      idleIcon,
      pendingIcon,
      successIcon,
      errorIcon,
      renderState,
      announcements,
      onClick,
      asChild,
      disabled,
      className,
      children,
      ...buttonProps
    },
    forwardedRef,
  ) => {
    if (process.env.NODE_ENV !== 'production' && asChild) {
      console.warn(
        '[ActionButton] asChild is not supported: ActionButton manages its own internal' +
          ' DOM layers for state crossfade. Ignoring asChild prop.',
      )
    }

    const prefersReducedMotion = useReducedMotion() ?? false
    const [currentState, setState] = useControlledActionState(
      controlledState,
      defaultState,
      onStateChange,
    )
    const [animateEnabled, setAnimateEnabled] = React.useState(false)

    React.useEffect(() => {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- one-time post-mount gate that avoids an initial-mount opacity flash
      setAnimateEnabled(true)
    }, [])

    const abortControllerRef = React.useRef<AbortController | null>(null)
    const resetTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)
    const minPendingTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)
    const pendingStartRef = React.useRef<number>(0)
    const isMountedRef = React.useRef(true)
    const isRunningRef = React.useRef(false)

    React.useEffect(() => {
      isMountedRef.current = true
      return () => {
        isMountedRef.current = false
      }
    }, [])

    React.useEffect(() => {
      return () => {
        if (resetTimerRef.current !== null) {
          clearTimeout(resetTimerRef.current)
          resetTimerRef.current = null
        }
        if (minPendingTimerRef.current !== null) {
          clearTimeout(minPendingTimerRef.current)
          minPendingTimerRef.current = null
        }
        if (abortControllerRef.current) {
          abortControllerRef.current.abort()
          abortControllerRef.current = null
        }
      }
    }, [])

    const scheduleReset = React.useCallback(() => {
      if (resetDelayMs <= 0) return
      if (resetTimerRef.current !== null) {
        clearTimeout(resetTimerRef.current)
      }
      resetTimerRef.current = setTimeout(() => {
        resetTimerRef.current = null
        if (!isMountedRef.current) return
        setState('idle')
      }, resetDelayMs)
    }, [resetDelayMs, setState])

    const transitionToTerminal = React.useCallback(
      (terminal: 'success' | 'error') => {
        const elapsed = Date.now() - pendingStartRef.current
        const remaining = Math.max(0, minPendingMs - elapsed)

        const applyTerminal = () => {
          if (!isMountedRef.current) return
          isRunningRef.current = false
          setState(terminal)
          scheduleReset()
        }

        if (remaining > 0) {
          minPendingTimerRef.current = setTimeout(() => {
            minPendingTimerRef.current = null
            applyTerminal()
          }, remaining)
        } else {
          applyTerminal()
        }
      },
      [minPendingMs, setState, scheduleReset],
    )

    const handleClick = React.useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        if (currentState !== 'idle') return

        onClick?.(event)

        if (!onAction || isRunningRef.current) return

        isRunningRef.current = true

        if (abortControllerRef.current) {
          abortControllerRef.current.abort()
        }

        const controller = new AbortController()
        abortControllerRef.current = controller

        if (resetTimerRef.current !== null) {
          clearTimeout(resetTimerRef.current)
          resetTimerRef.current = null
        }

        pendingStartRef.current = Date.now()
        setState('pending')

        onAction(controller.signal).then(
          () => {
            if (controller.signal.aborted) return
            transitionToTerminal('success')
          },
          (err: unknown) => {
            if (controller.signal.aborted) return
            if (err instanceof DOMException && err.name === 'AbortError') return
            transitionToTerminal('error')
          },
        )
      },
      [currentState, onClick, onAction, setState, transitionToTerminal],
    )

    const isDisabled = disabled || currentState === 'pending'

    const resolveIdleContent = () => {
      if (renderState) return renderState('idle')
      return (
        <>
          {idleIcon}
          {idleLabel ?? children}
        </>
      )
    }

    const resolvePendingContent = () => {
      if (renderState) return renderState('pending')
      return (
        <>
          {pendingIcon ?? <DefaultSpinnerIcon />}
          {pendingLabel ?? idleLabel ?? children}
        </>
      )
    }

    const resolveSuccessContent = () => {
      if (renderState) return renderState('success')
      return (
        <>
          {successIcon ?? <DefaultCheckIcon />}
          {successLabel ?? 'Done'}
        </>
      )
    }

    const resolveErrorContent = () => {
      if (renderState) return renderState('error')
      return (
        <>
          {errorIcon ?? <DefaultErrorIcon />}
          {errorLabel ?? 'Failed'}
        </>
      )
    }

    const ariaLabel =
      announcements?.[currentState] ?? (buttonProps['aria-label'] as string | undefined)

    return (
      <>
        <Button
          ref={forwardedRef}
          {...buttonProps}
          className={cn('relative overflow-hidden', className)}
          disabled={isDisabled}
          aria-disabled={isDisabled || undefined}
          aria-busy={currentState === 'pending' || undefined}
          aria-label={ariaLabel}
          data-state={currentState}
          onClick={handleClick}
          asChild={false}
        >
          {/* Invisible sizing layer, grid-stacks all states so the widest determines width */}
          <span className="invisible grid [&>*]:col-start-1 [&>*]:row-start-1" aria-hidden="true">
            <span className="inline-flex items-center gap-2">{resolveIdleContent()}</span>
            <span className="inline-flex items-center gap-2">{resolvePendingContent()}</span>
            <span className="inline-flex items-center gap-2">{resolveSuccessContent()}</span>
            <span className="inline-flex items-center gap-2">{resolveErrorContent()}</span>
          </span>
          <StateLayer
            active={currentState === 'idle'}
            reducedMotion={prefersReducedMotion}
            animateEnabled={animateEnabled}
          >
            {resolveIdleContent()}
          </StateLayer>
          <StateLayer
            active={currentState === 'pending'}
            reducedMotion={prefersReducedMotion}
            animateEnabled={animateEnabled}
          >
            {resolvePendingContent()}
          </StateLayer>
          <StateLayer
            active={currentState === 'success'}
            reducedMotion={prefersReducedMotion}
            animateEnabled={animateEnabled}
          >
            {resolveSuccessContent()}
          </StateLayer>
          <StateLayer
            active={currentState === 'error'}
            reducedMotion={prefersReducedMotion}
            animateEnabled={animateEnabled}
          >
            {resolveErrorContent()}
          </StateLayer>
        </Button>
        <span className="sr-only" role="status" aria-live="polite" aria-atomic="true">
          {announcements?.[currentState] ?? ''}
        </span>
      </>
    )
  },
)

ActionButton.displayName = 'ActionButton'

export function ActionButtonPreview() {
  const [demoState, setDemoState] = React.useState<ActionButtonState>('idle')

  const simulateAction = React.useCallback(async (signal: AbortSignal) => {
    await new Promise<void>((resolve, reject) => {
      const timer = setTimeout(resolve, 1500)
      signal.addEventListener('abort', () => {
        clearTimeout(timer)
        reject(new DOMException('Aborted', 'AbortError'))
      })
    })
  }, [])

  return (
    <div className="flex flex-col items-center justify-center gap-6 p-6">
      <div className="flex flex-wrap items-center justify-center gap-3">
        <ActionButton
          onAction={simulateAction}
          idleLabel="Save"
          pendingLabel="Saving…"
          successLabel="Saved"
          errorLabel="Error"
          minPendingMs={600}
          announcements={{
            pending: 'Saving…',
            success: 'Saved successfully',
            error: 'Save failed',
          }}
        />
        <ActionButton
          variant="outline"
          onAction={async () => {
            await new Promise((_, rej) => setTimeout(() => rej(new Error('fail')), 1200))
          }}
          idleLabel="Submit"
          pendingLabel="Submitting…"
          errorLabel="Retry"
          minPendingMs={400}
        />
      </div>

      <div className="flex flex-wrap items-center justify-center gap-2">
        {(['idle', 'pending', 'success', 'error'] as const).map((s) => (
          <button
            key={s}
            type="button"
            onClick={() => setDemoState(s)}
            className={cn(
              'rounded-md border px-2 py-1 text-xs capitalize',
              demoState === s
                ? 'border-(--color-accent) text-(--color-accent)'
                : 'border-(--color-border) text-(--color-muted)',
            )}
          >
            {s}
          </button>
        ))}
      </div>
      <ActionButton state={demoState} idleLabel="Controlled" variant="outline" />
    </div>
  )
}

'use client'

import * as React from 'react'
import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'
import { animate, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'
import { playClickSound, playHoverSound } from '@/lib/sound'

export const buttonVariants = cva(
  [
    'inline-flex items-center justify-center gap-2 whitespace-nowrap font-normal',
    'rounded-md squircle-corners',
    'select-none',
    'transition-colors duration-(--motion-dur-fast) ease-(--motion-ease-out)',
    'motion-reduce:transition-none motion-reduce:transform-none',
    'focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-2 focus-visible:ring-offset-(--color-bg)',
    'focus-visible:outline-none',
    'disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50',
    'aria-disabled:pointer-events-none aria-disabled:cursor-not-allowed aria-disabled:opacity-50',
  ].join(' '),
  {
    variants: {
      variant: {
        solid: 'bg-(--color-fg) text-(--color-bg) hover:bg-(--color-fg)/90',
        outline: 'border border-(--color-border) text-(--color-fg) hover:bg-(--color-surface)',
        ghost: 'text-(--color-fg) hover:bg-(--color-surface-2)',
        link: 'text-(--color-fg) underline-offset-4 hover:underline',
        destructive:
          'bg-(--color-error) text-(--color-bg) hover:bg-(--color-error)/90 focus-visible:ring-(--color-error)',
      },
      size: {
        sm: 'min-h-9 px-3 text-xs',
        md: 'min-h-11 px-4 text-sm',
        lg: 'min-h-12 px-5 text-base',
        'icon-sm': 'size-9 shrink-0 p-0',
        icon: 'size-11 shrink-0 p-0',
        'icon-lg': 'size-12 shrink-0 p-0',
      },
    },
    defaultVariants: {
      variant: 'solid',
      size: 'md',
    },
  },
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean
  loading?: boolean
  /** Accessible label announced while an action is in progress. */
  loadingLabel?: string
  /** Replaces the default progress glyph without changing loading behavior. */
  loadingIndicator?: React.ReactNode
  /** @deprecated Use `variant="destructive"`. */
  destructive?: boolean
  className?: string
}

function DefaultLoadingIndicator() {
  return (
    <svg
      className="size-4 animate-spin motion-reduce:animate-none"
      viewBox="0 0 24 24"
      fill="none"
      aria-hidden="true"
    >
      <circle
        cx="12"
        cy="12"
        r="10"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        className="opacity-25"
      />
      <path
        d="M12 2a10 10 0 0 1 10 10"
        stroke="currentColor"
        strokeWidth="2.5"
        strokeLinecap="round"
        className="opacity-75"
      />
    </svg>
  )
}

function ButtonLoadingContent({
  children,
  indicator,
}: {
  children: React.ReactNode
  indicator?: React.ReactNode
}) {
  return (
    <span className="relative inline-flex min-w-0 items-center justify-center">
      <span className="invisible inline-flex items-center gap-2" aria-hidden="true">
        {children}
      </span>
      <span className="absolute inset-0 flex items-center justify-center">
        {indicator ?? <DefaultLoadingIndicator />}
      </span>
    </span>
  )
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      loading = false,
      loadingLabel,
      loadingIndicator,
      destructive = false,
      disabled,
      type = 'button',
      tabIndex,
      onClick,
      onPointerDown,
      onPointerUp,
      onPointerCancel,
      onPointerLeave,
      onMouseEnter,
      children,
      style,
      'aria-label': ariaLabel,
      ...props
    },
    forwardedRef,
  ) => {
    const internalRef = React.useRef<HTMLButtonElement | null>(null)
    const pressedRef = React.useRef(false)
    const prefersReducedMotion = useReducedMotion()
    const isDisabled = disabled || loading
    const resolvedVariant =
      destructive && (variant === undefined || variant === 'solid') ? 'destructive' : variant
    const destructiveClasses = destructive
      ? variant === 'outline'
        ? 'border-(--color-error) text-(--color-error) hover:bg-(--color-error)/10 focus-visible:ring-(--color-error)'
        : variant === 'ghost'
          ? 'text-(--color-error) hover:bg-(--color-error)/10 focus-visible:ring-(--color-error)'
          : variant === 'link'
            ? 'text-(--color-error) focus-visible:ring-(--color-error)'
            : undefined
      : undefined

    const setRefs = React.useCallback(
      (node: HTMLButtonElement | null) => {
        internalRef.current = node
        if (typeof forwardedRef === 'function') {
          forwardedRef(node)
        } else if (forwardedRef) {
          forwardedRef.current = node
        }
      },
      [forwardedRef],
    )

    const settle = React.useCallback(() => {
      if (!pressedRef.current) return
      pressedRef.current = false
      const element = internalRef.current
      if (!element) return
      animate(element, { scale: 1, y: 0 }, { ...springs.settle })
    }, [])

    const handlePointerDown = React.useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerDown?.(event)
        if (event.defaultPrevented || isDisabled || prefersReducedMotion) return

        const element = internalRef.current
        if (!element) return
        pressedRef.current = true
        animate(element, { scale: 0.97, y: 1 }, { ...springs.press })
      },
      [onPointerDown, isDisabled, prefersReducedMotion],
    )

    const handlePointerUp = React.useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerUp?.(event)
        settle()
      },
      [onPointerUp, settle],
    )

    const handlePointerCancel = React.useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerCancel?.(event)
        settle()
      },
      [onPointerCancel, settle],
    )

    const handlePointerLeave = React.useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerLeave?.(event)
        settle()
      },
      [onPointerLeave, settle],
    )

    const handleClick = React.useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        if (isDisabled) {
          event.preventDefault()
          event.stopPropagation()
          return
        }
        playClickSound()
        onClick?.(event)
      },
      [onClick, isDisabled],
    )

    const handleMouseEnter = React.useCallback(
      (event: React.MouseEvent<HTMLButtonElement>) => {
        if (!isDisabled) playHoverSound()
        onMouseEnter?.(event)
      },
      [onMouseEnter, isDisabled],
    )

    const loadingContent = (content: React.ReactNode) => (
      <ButtonLoadingContent indicator={loadingIndicator}>{content}</ButtonLoadingContent>
    )

    let renderedChildren: React.ReactNode = loading ? loadingContent(children) : children
    if (asChild) {
      const child = React.Children.only(children) as React.ReactElement<{
        children?: React.ReactNode
      }>
      renderedChildren = React.cloneElement(
        child,
        undefined,
        loading ? loadingContent(child.props.children) : child.props.children,
      )
    }

    const Comp = asChild ? Slot : 'button'

    return (
      <Comp
        ref={setRefs}
        type={asChild ? undefined : type}
        className={cn(
          buttonVariants({ variant: resolvedVariant, size }),
          destructiveClasses,
          className,
        )}
        disabled={asChild ? undefined : isDisabled}
        tabIndex={asChild && isDisabled ? -1 : tabIndex}
        aria-label={loading && loadingLabel ? loadingLabel : ariaLabel}
        aria-disabled={isDisabled || undefined}
        aria-busy={loading || undefined}
        data-loading={loading ? '' : undefined}
        data-disabled={isDisabled ? '' : undefined}
        data-variant={resolvedVariant ?? 'solid'}
        data-size={size ?? 'md'}
        onClick={handleClick}
        onPointerDown={handlePointerDown}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerCancel}
        onPointerLeave={handlePointerLeave}
        onMouseEnter={handleMouseEnter}
        {...props}
        style={style}
      >
        {renderedChildren}
      </Comp>
    )
  },
)

Button.displayName = 'Button'

export function ButtonPreview() {
  return (
    <div className="flex flex-wrap items-center justify-center gap-3 p-6">
      <Button variant="solid">Solid</Button>
      <Button variant="outline">Outline</Button>
      <Button variant="ghost">Ghost</Button>
      <Button variant="link">Link</Button>
    </div>
  )
}

export const durations = {
  instant: '50ms',
  fast: '120ms',
  base: '200ms',
  slow: '320ms',
} as const

export const easings = {
  out: 'cubic-bezier(0.22, 1, 0.36, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
} as const

export const springs = {
  fast: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
  press: { type: 'spring', stiffness: 700, damping: 32, mass: 1 },
  moderate: { type: 'spring', stiffness: 300, damping: 24, mass: 1 },
  settle: { type: 'spring', stiffness: 260, damping: 26, mass: 1 },
} as const

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

